function applyLang() {
  document.querySelectorAll("[data-lang]").forEach(el => {
    const key = el.getAttribute("data-lang");
    if (text[lang][key]) {
      el.innerText = text[lang][key];
    }
  });

  const icon = document.getElementById("langIcon");
  const langTextEl = document.getElementById("langText");
  if (icon) {
    icon.src = lang === "kh"
      ? "https://flagcdn.com/w40/kh.png"
      : "https://flagcdn.com/w40/gb.png";
  }
  if (langTextEl) {
    langTextEl.textContent = lang === "kh" ? "KH" : "EN";
  }
}

function toggleLang() {
  lang = (lang === "kh") ? "en" : "kh";
  localStorage.setItem("lang", lang);
  applyLang();
}

// =======================
// DARK MODE (CLEAN)
// =======================
const modeBtn = document.querySelector(".mode");

if (modeBtn) {
  let theme = localStorage.getItem("theme") || "light";

  function applyTheme() {
    document.body.classList.toggle("dark", theme === "dark");
    modeBtn.innerText = theme === "dark" ? "☀️" : "🎨";
  }

  modeBtn.addEventListener("click", () => {
    theme = theme === "dark" ? "light" : "dark";
    localStorage.setItem("theme", theme);
    applyTheme();
  });

  applyTheme();
}

window.addEventListener("DOMContentLoaded", applyLang);
// =======================
// NAV DROPDOWN FIX
document.querySelectorAll(".dropdown").forEach(drop => {
  const toggle = drop.querySelector(".dropdown-toggle");

  toggle.addEventListener("click", (e) => {
    e.stopPropagation();

    // close others
    document.querySelectorAll(".dropdown").forEach(d => {
      if (d !== drop) d.classList.remove("active");
    });

    // toggle current
    drop.classList.toggle("active");
  });
});

// click outside closes
document.addEventListener("click", () => {
  document.querySelectorAll(".dropdown").forEach(d => {
    d.classList.remove("active");
  });
});
// hamburger menu handler
const hamburger = document.querySelector(".hamburger");
if (hamburger) {
  hamburger.addEventListener("click", (e) => {
    e.stopPropagation();
    const menu = document.querySelector(".menu");
    menu.classList.toggle("active");
    if (menu.classList.contains("active")) {
      document.querySelectorAll(".dropdown").forEach(d => {
        d.classList.remove("active");
      });
    }
  });
}

// =======================
// LANGUAGE DROPDOWN HANDLER
// =======================
function setupLanguageHandlers() {
  const langToggle = document.getElementById("langToggle");
  const langMenu = document.querySelector(".lang-menu");
  const langDropdown = document.querySelector(".lang-dropdown");

  if (langToggle) {
    langToggle.addEventListener("click", (e) => {
      e.stopPropagation();
      langMenu.classList.toggle("active");
    });

    document.querySelectorAll(".lang-option").forEach(option => {
      option.addEventListener("click", (e) => {
        e.stopPropagation();
        const selectedLang = option.getAttribute("data-lang");
        lang = selectedLang;
        localStorage.setItem("lang", lang);
        applyLang();
        langMenu.classList.remove("active");
      });
    });

    document.addEventListener("click", (e) => {
      if (!langDropdown.contains(e.target)) {
        langMenu.classList.remove("active");
      }
    });
  }
}

// Call on page load
window.addEventListener("DOMContentLoaded", () => {
  setupLanguageHandlers();
});
